// Sprite loading and drawing. Sheets are generated by tools/gen-sprites.mjs;
// each sheet lays its animation frames left to right.

const ASSET_ROOT = "assets/";

export const art = {
  ready: false,
  players: [],
  sheets: {},
};

function loadImage(src) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = ASSET_ROOT + src.replace(/^assets\//, "");
  });
}

export async function loadArt() {
  try {
    const res = await fetch(ASSET_ROOT + "sprites.json", { cache: "no-store" });
    const manifest = await res.json();
    const jobs = [];
    for (const p of manifest.players) {
      jobs.push(loadImage(p.file).then((img) => (art.players[p.file] = img ? { img, frameW: p.frameW, frameH: p.frameH, frames: p.frames } : null)));
    }
    for (const [name, s] of Object.entries(manifest.sheets)) {
      jobs.push(loadImage(s.file).then((img) => (art.sheets[name] = img ? { img, frameW: s.frameW, frameH: s.frameH, frames: s.frames } : null)));
    }
    await Promise.all(jobs);
    art.ready = Object.values(art.sheets).some(Boolean) && art.players.some(Boolean);
    return art.ready;
  } catch {
    art.ready = false;
    return false;
  }
}

export function playerArt(slot) {
  if (!art.players.length) return null;
  return art.players[`assets/survivor-${(slot % 4) + 1}.png`] || art.players["assets/survivor-1.png"];
}

/** Draw one frame of a sheet, centred at (x,y), rotated to face `angle`. */
export function drawSheet(ctx, sheet, frame, x, y, angle, size, opts = {}) {
  if (!sheet) return false;
  const f = sheet.frames > 1 ? frame % sheet.frames : 0;
  const scale = size / sheet.frameW;
  ctx.save();
  ctx.translate(x, y);
  if (angle) ctx.rotate(angle);
  if (opts.flipY) ctx.scale(1, -1);
  ctx.globalAlpha = opts.alpha ?? 1;
  if (opts.flash) {
    ctx.filter = "brightness(2.4) saturate(.4)";
  }
  ctx.drawImage(sheet.img, f * sheet.frameW, 0, sheet.frameW, sheet.frameH, (-sheet.frameW * scale) / 2, (-sheet.frameH * scale) / 2, sheet.frameW * scale, sheet.frameH * scale);
  ctx.filter = "none";
  ctx.restore();
  return true;
}

export function drawFrame(ctx, sheet, frame, x, y, size, alpha = 1) {
  if (!sheet) return false;
  const f = frame % sheet.frames;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.drawImage(sheet.img, f * sheet.frameW, 0, sheet.frameW, sheet.frameH, x - size / 2, y - size / 2, size, size);
  ctx.restore();
  return true;
}
